window.bookSummaryJSON = "<p><b>From the Arthur C. Clarke award-winning author of <i>Children of Time</i>, this third and final novel in an extraordinary space opera trilogy depicts humanity on the brink of extinction—and reveals how one man's discovery will save or destroy us all.</b><br><br> Lords of Uncreation is the final high-octane installment in Adrian Tchaikovsky's Final Architecture space opera trilogy.<br><br><br><b>The Final Architecture</b><br><i>Shards of Earth<br> Eyes of the Void<br> Lords of Uncreation </i></p>"; 
